import{AGUA_ACTIVA as f}from"../sim/terreno.js?v=b72f93d";import{sitiosQue as d,sitiosConMarabunta as v,nocturnasDe as b}from"./fauna.js?v=b72f93d";const e=(t,r)=>({es:t,en:r}),a=(t,r=t)=>({es:t,en:r}),l={arana:["la ara\xF1a","the spider"],"arana-errante":["la ara\xF1a errante","the wandering spider"],escorpion:["el escorpi\xF3n","the scorpion"],escolopendra:["la escolopendra","the centipede"]},u={es:new Intl.ListFormat("es",{type:"conjunction"}),en:new Intl.ListFormat("en",{type:"conjunction"})},h=t=>t.charAt(0).toUpperCase()+t.slice(1),n=t=>{const r=b(t).filter(i=>l[i]);return{etiqueta:e("De noche","At night"),valor:a(h(u.es.format(r.map(i=>l[i][0]))),h(u.en.format(r.map(i=>l[i][1]))))}},s=v(),c=t=>t.mapa&&t.mapa.terreno||{},m=d(t=>(c(t).agua||{}).lagunas>0),p=d(t=>!!(c(t).agua||{}).archipielago),o=(t,r,i,g,y)=>({id:`mundo/${t}`,seccion:"mundo",icono:r,contenido:i,datos:g,relacionadas:y}),T=[o("clima","hoja",{es:{titulo:"El clima",subtitulo:"Estaciones y d\xEDa y noche, dos relojes engranados",resumen:"Un a\xF1o de cuatro estaciones \u2014una semana de juego cada una\u2014 y un ciclo de luz con amanecer y atardecer. Cambian el ritmo del mundo: cu\xE1nto brota, qu\xE9 fauna sale y cu\xE1nto castiga estar fuera.",bloques:[{titulo:"Estaciones",texto:"La primavera dobla los brotes de comida y el invierno los deja en un tercio. Las transiciones son suaves: el deshielo se ve venir, y el \xFAltimo tramo de cada estaci\xF3n ya vira hacia la siguiente."},{titulo:"D\xEDa y noche",texto:"La luz baja con rampas de atardecer y amanecer. De noche se ve menos lejos, los insectos se esconden y salen amenazas que no se ven. Los d\xEDas de verano son m\xE1s largos que los de invierno, y CU\xC1NTO m\xE1s lo decide el sitio: en el ecuador no cambia nada y cerca del c\xEDrculo polar el invierno se queda en cinco horas y media de luz."},{titulo:"La temperatura",texto:"Sube y baja con la estaci\xF3n y con la hora, con la inercia del suelo: el fr\xEDo aprieta despu\xE9s de anochecer y el m\xEDnimo llega de madrugada. El term\xF3metro de la barra la marca en grados, y el campo suena con ella: b\xFAho y grillos en la noche templada, chicharras cuando aprieta el verano y viento helado cuando baja de seis grados."}],consejo:"Elige el comienzo en el di\xE1logo de partida: el est\xE1ndar arranca en primavera y de d\xEDa \u2014 la temporada de acopio antes del primer invierno. Al azar puede tocar cualquier estaci\xF3n, salvo el invierno en los sitios donde el d\xEDa de invierno no pasa de siete grados: ah\xED ninguna partida empieza con la colonia helada.",palabras:["estaciones","noche","temperatura","luz","clima","sonido","ambiente"]},en:{titulo:"The weather",subtitulo:"Seasons and day-night, two geared clocks",resumen:"A year of four seasons \u2014 a week of play each \u2014 and a light cycle with dawn and dusk. They set the world\u2019s rhythm: how much food sprouts, which wildlife shows up and how much it costs to stay outside.",bloques:[{titulo:"Seasons",texto:"Spring doubles food sprouts and winter cuts them to a third. Transitions are smooth: the thaw can be seen coming, and the last stretch of each season already leans into the next."},{titulo:"Day and night",texto:"Light fades with dusk and dawn ramps. At night you see less far, insects hide and unseen threats come out. Summer days are longer than winter ones, and HOW MUCH longer is decided by the place: on the equator nothing changes, and near the polar circle winter is down to five and a half hours of light."},{titulo:"Temperature",texto:"It rises and falls with the season and the hour, with the ground\u2019s inertia: cold bites after nightfall and bottoms out before dawn. The top-bar thermometer shows it in degrees, and the field sounds along with it: owl and crickets on a warm night, cicadas when summer bites, and freezing wind once it drops below six degrees."}],consejo:"Pick the start in the match dialog: the standard opens in spring at daytime \u2014 the stockpiling season before the first winter. A random start can land in any season, except winter in the places where a winter day does not get above seven degrees: no match there begins with the colony frozen.",palabras:["seasons","night","temperature","light","weather","sound","ambience"]}},null,["mundo/sitio","mundo/lluvia","mundo/noche","mundo/invierno"]),o("lluvia","hoja",{es:{titulo:"La lluvia y los charcos",subtitulo:"Cu\xE1ndo llueve, hasta d\xF3nde sube el agua y a qui\xE9n se lleva",resumen:"La lluvia no cae al azar: cada clima tiene su estaci\xF3n de lluvias y su hora, y como mucho un chaparr\xF3n al d\xEDa. Mientras llueve el agua corre a los huecos y los llena; al escampar, el sol la seca, m\xE1s de d\xEDa que de noche. El icono junto al de d\xEDa y noche dice qu\xE9 tiempo hace.",bloques:[{titulo:"Cu\xE1ndo llueve",texto:"Lo decide el clima del sitio. El mediterr\xE1neo casi no llueve en verano y descarga en oto\xF1o; el monz\xF3n es al rev\xE9s, empapa el verano y deja seco el invierno; los climas de tormenta llueven por la tarde. Los sitios h\xFAmedos llueven m\xE1s a menudo y m\xE1s largo, pero siempre hay ratos secos entre chaparr\xF3n y chaparr\xF3n. Bajo el aguacero las hormigas andan hasta un cuarenta por ciento m\xE1s lentas, y nadie vuela: la reina en vuelo nupcial se posa y espera a que escampe, sin perder las alas (la llovizna no la derriba)."},{titulo:"El charco",texto:"La lluvia corre al hueco m\xE1s cercano y lo llena: las pozas, el escal\xF3n m\xE1s bajo y tambi\xE9n las hondonadas de lo alto. Un hueco lleno rebosa y el agua sigue subiendo hasta donde llegue. Sube poco a poco \u2014nunca de golpe\u2014 y se va con el sol. Con menos de un palmo de fondo es LODO: se pisa y se cruza. M\xE1s hondo ya es agua, y ninguna hormiga entra. CON FR\xCDO cambia todo: hacia los tres grados cae aguanieve y hacia uno, nieve (con el aire seco, un poco antes). La nieve cuaja \u2014de noche m\xE1s en lo alto; al sol aguanta m\xE1s en la umbr\xEDa de abajo\u2014, deja el suelo blanco y no encharca hasta que se funde; entonces la mitad empapa la tierra y el resto baja a los huecos. Y bajo cero los charcos se hielan desde la orilla, m\xE1s adentro cuanto m\xE1s fr\xEDo: el hielo se pisa, no ahoga ni anega el hormiguero, y el agua helada no baja de nivel."},{titulo:"Qui\xE9n se ahoga",texto:"La hormiga que se queda con el agua por encima del lodo se ahoga, salvo la ROJA, que flota. Un hormiguero con la boca bajo el agua aguanta unos cuarenta y cinco turnos y se pierde con todo lo que tenga dentro; cada especie lo lleva a su manera: la cortadora, con su jard\xEDn de hongo hondo, cae la primera (en menos de la mitad); la bulldog tambi\xE9n antes de tiempo; la tejedora, que anida en alto, aguanta el doble; la roja, en balsa, casi nunca."}],consejo:"Mira en qu\xE9 estaci\xF3n llueve tu sitio antes de fundar. En los h\xFAmedos, un hormiguero en la poza come mejor pero se ahoga en la primera crecida: la especie decide cu\xE1nto riesgo te puedes permitir.",palabras:["lluvia","charco","lodo","barro","agua","ahogar","inundar","tormenta","monz\xF3n","tiempo","clima","nieve","aguanieve","hielo","helada","deshielo"]},en:{titulo:"Rain and puddles",subtitulo:"When it rains, how high the water rises and whom it takes",resumen:"Rain does not fall at random: each climate has its rainy season and its hour, and at most one shower a day. While it rains the water runs into the hollows and fills them; once it stops, the sun dries it, more by day than by night. The icon next to the day-night one tells you the weather.",bloques:[{titulo:"When it rains",texto:"The place\u2019s climate decides. The Mediterranean barely rains in summer and pours in autumn; the monsoon is the reverse, soaking the summer and leaving winter dry; stormy climates rain in the afternoon. Wet places rain more often and for longer, but there are always dry spells between showers. In a downpour ants walk up to forty percent slower, and nobody flies: a queen on her nuptial flight lands and waits for it to clear, keeping her wings (drizzle does not bring her down)."},{titulo:"The puddle",texto:"Rain runs to the nearest hollow and fills it: the pools, the lowest step and also the hollows up on high ground. A full hollow overflows and the water keeps rising as far as it reaches. It rises little by little \u2014 never all at once \u2014 and the sun takes it away. Under a hand\u2019s depth it is MUD: ants walk through it. Deeper it is water, and no ant goes in. COLD changes everything: at about three degrees sleet falls and at about one, snow (a little sooner in dry air). Snow settles \u2014 more on high ground at night; in the sun it lasts longer in the shade below \u2014, turns the ground white and does not pool until it melts; then half soaks into the soil and the rest runs down to the hollows. Below zero puddles freeze from the edge, further in the colder it gets: ice can be walked on, does not drown ants or flood the anthill, and frozen water does not drop."},{titulo:"Who drowns",texto:"An ant left with water above the mud drowns, except the RED ant, which floats. An anthill with its mouth under water holds out about forty-five turns and is then lost with everything inside; each species takes it its own way: the leafcutter, with its deep fungus garden, falls first (in under half that); the bulldog also early; the weaver, nesting high, lasts twice as long; the red ant, on its raft, almost never."}],consejo:"Check which season your place rains in before founding. In wet places a nest in a pool eats better but drowns in the first flood: the species decides how much risk you can afford.",palabras:["rain","puddle","mud","water","drown","flood","storm","monsoon","weather","climate","snow","sleet","ice","frost","thaw"]}},[{etiqueta:e("Chaparrones","Showers"),valor:a("Como mucho uno al d\xEDa","At most one a day")},{etiqueta:e("Lodo","Mud"),valor:a("Menos de 0,15 de fondo: se cruza","Under 0.15 deep: walkable")},{etiqueta:e("Con aguacero","In a downpour"),valor:a("Hasta un 40 % m\xE1s lentas; nadie vuela","Up to 40% slower; nobody flies")},{etiqueta:e("Nido anegado","Flooded nest"),valor:a("~45 turnos, seg\xFAn la especie","~45 turns, by species")},{etiqueta:e("No se ahoga","Does not drown"),valor:a("La roja: flota","The red ant: it floats")},{etiqueta:e("Nieve","Snow"),valor:a("Bajo 1 \xB0C; aguanieve hasta 3 \xB0C","Below 1 \xB0C; sleet up to 3 \xB0C")},{etiqueta:e("Charco helado","Frozen puddle"),valor:a("Bajo 0 \xB0C, desde la orilla: se pisa","Below 0 \xB0C, from the edge: walkable")}],["mundo/relieve","mundo/clima","hormiguero/fundacion"]),o("relieve","idioma",{es:{titulo:"El relieve",subtitulo:"Escalones, rampas y d\xF3nde se junta el agua",resumen:"El suelo tiene niveles: del llano a la cumbre, doce o trece en casi todos los sitios, cinco en el Amazonas y ninguno en el Oasis, que es llano. Entre nivel y nivel siempre hay una rampa de uno: no hay acantilados. La base no es una sola planicie sino tres escalones, as\xED que la lluvia nunca anega todo el llano a la vez.",bloques:[{titulo:"Cuestas",texto:"Subir cuesta: cada nivel que se sube a la vez deja el paso en la mitad. Bajar sale a cuenta, un veinte por ciento m\xE1s r\xE1pido por nivel. Las rutas lo saben y rodean la colina cuando rodear es m\xE1s corto en turnos. Y EL SUELO TAMBI\xC9N CUENTA: la hierba espesa de los sitios h\xFAmedos frena hasta un cuarenta por ciento, el barro la mitad y la nieve cuajada hasta un sesenta; las rutas buscan los claros cuando compensa. Y cada altura tiene su temperatura: el term\xF3metro marca la de media ladera; lo alto est\xE1 expuesto, se calienta m\xE1s al sol y se enfr\xEDa m\xE1s de noche; lo bajo queda a la sombra y h\xFAmedo, m\xE1s fresco de d\xEDa y m\xE1s templado de madrugada."},{titulo:"Pozas y escalones",texto:"En los sitios h\xFAmedos hay POZAS: hondonadas repartidas por el mapa, lo \xFAnico a cota cero, donde se junta el agua primero. La base del mapa se reparte en tres escalones: cuando llueve fuerte se moja el de abajo y los otros dos quedan secos. El Amazonas va aparte: un r\xEDo que no se seca nunca, con dos terrazas de vega que se inundan en la crecida y tierra firme detr\xE1s."},{titulo:"Fundar abajo o arriba",texto:"La comida brota m\xE1s y m\xE1s gorda junto al agua \u2014las pozas cuentan como orilla\u2014 y bajo los \xE1rboles. Fundar abajo es comer bien y arriesgar el nido en cada crecida; fundar arriba es dormir seco y andar m\xE1s. El bot\xF3n de anidar avisa cuando el sitio que miras se inunda. Y PARA PELEAR, ARRIBA: la que pisa la casilla m\xE1s alta muerde y aguanta un veinte por ciento m\xE1s que la que le llega desde abajo."}],consejo:"La roja puede fundar en la poza sin miedo; la cortadora, no. Con cualquier otra, busca el escal\xF3n de en medio junto a una poza: cerca de la comida y por encima de la crecida.",palabras:["relieve","nivel","altura","cuesta","rampa","poza","escal\xF3n","colina","r\xEDo","terreno","fundar"]},en:{titulo:"The terrain",subtitulo:"Steps, ramps and where the water gathers",resumen:"The ground has levels: from the plain to the summit, twelve or thirteen in almost every place, five in the Amazon and none in the Oasis, which is flat. Between one level and the next there is always a one-level ramp: no cliffs. The base is not a single plain but three steps, so the rain never floods the whole plain at once.",bloques:[{titulo:"Slopes",texto:"Climbing costs: each level climbed at once halves the step. Going down pays off, twenty percent faster per level. Routes know it and go around a hill when that is fewer turns. THE GROUND COUNTS TOO: the thick grass of wet places slows ants by up to forty percent, mud by half and settled snow by up to sixty; routes look for clearings when it pays. And every height has its own temperature: the thermometer shows the mid-slope one; high ground is exposed, warming more in the sun and cooling more at night; low ground stays shaded and damp, cooler by day and milder before dawn."},{titulo:"Pools and steps",texto:"Wet places have POOLS: hollows scattered across the map, the only ground at level zero, where water gathers first. The map\u2019s base is split into three steps: in heavy rain the bottom one gets wet and the other two stay dry. The Amazon is its own thing: a river that never dries, two floodplain terraces that go under in the flood, and firm land behind."},{titulo:"Found low or high",texto:"Food sprouts more often and richer next to water \u2014 pools count as shore \u2014 and under the trees. Founding low means eating well and risking the nest in every flood; founding high means sleeping dry and walking further. The nest button warns you when the spot you are looking at floods. And TO FIGHT, BE ON TOP: the ant standing on the higher cell bites and holds twenty percent harder than the one coming at her from below."}],consejo:"The red ant can found in a pool without fear; the leafcutter cannot. With any other, look for the middle step next to a pool: close to the food and above the flood.",palabras:["terrain","level","height","slope","ramp","pool","step","hill","river","ground","found"]}},[{etiqueta:e("Niveles","Levels"),valor:a("12 o 13; 5 en el Amazonas; llano en el Oasis","12 or 13; 5 in the Amazon; flat in the Oasis")},{etiqueta:e("Subir un nivel","Climbing one level"),valor:a("Paso a la mitad","Half the step")},{etiqueta:e("Bajar un nivel","Going down one level"),valor:a("Un 20 % m\xE1s r\xE1pido","20% faster")},{etiqueta:e("La base","The base"),valor:a("Tres escalones","Three steps")},{etiqueta:e("Pelear desde arriba","Fighting from above"),valor:a("Ataque y defensa \xD71,2","Attack and defence \xD71.2")}],["mundo/lluvia","mundo/agua","hormiguero/fundacion"]),o("sitio","idioma",{es:{titulo:"El sitio",subtitulo:"D\xF3nde juegas decide el a\xF1o que te toca",resumen:"Cada escenario es un lugar del mundo, con su clima y su latitud. No se eligen por separado: eliges el sitio y el sitio los trae. De ah\xED salen el fr\xEDo, el calor y \u2014lo que casi nadie mira\u2014 cu\xE1ntas horas de luz tiene el d\xEDa en cada estaci\xF3n.",bloques:[{titulo:"Siete climas",texto:"El mediterr\xE1neo es el de siempre. El OCE\xC1NICO apenas hiela y tiene el a\xF1o m\xE1s suave; el CONTINENTAL hiela tambi\xE9n de d\xEDa en invierno y achicharra en verano. El DES\xC9RTICO no destaca por el calor sino por el salto entre el mediod\xEDa y el amanecer, veinte grados, y por eso hiela de noche aunque el d\xEDa haya sido templado. El TROPICAL es c\xE1lido todo el a\xF1o y no hiela nunca; sus noches refrescan poco donde el aire est\xE1 empapado o hay mar cerca y hasta diecis\xE9is grados en la estaci\xF3n seca de los sitios secos, y su invierno se nota m\xE1s cuanto m\xE1s lejos del ecuador. El ECUATORIAL directamente no tiene a\xF1o: las cuatro estaciones se parecen. Y la ALTA MONTA\xD1A tiene el invierno m\xE1s duro de todos \u2014hasta cinco bajo cero de d\xEDa y diez de madrugada, el \xFAnico clima que baja de los cinco bajo cero\u2014 con un verano corto pero de verdad: es el \xFAnico sitio donde el a\xF1o entero se juega a llegar al buen tiempo con la colonia en pie."},{titulo:"La latitud manda en la luz",texto:"Cuanto m\xE1s lejos del ecuador, m\xE1s se separan el verano y el invierno. En el Amazonas el d\xEDa dura doce horas los trescientos sesenta y cinco d\xEDas; en el fiordo va de cinco horas y media en pleno invierno a dieciocho y media en pleno verano. Eso cambia la partida entera: cu\xE1nto rato se puede forrajear, cu\xE1nta noche hay que aguantar y cu\xE1ntas horas caza la ara\xF1a."},{titulo:"La altura enfr\xEDa",texto:"Cada mil metros quitan seis grados y medio, igual que en el mundo real. Por eso la sabana, a novecientos metros, juega seis grados por debajo de lo que su tr\xF3pico promete \u2014y aun as\xED no hiela\u2014, y la pradera, a quinientos, hiela de madrugada tres estaciones de cuatro. Ni el clima, ni la altitud, ni la latitud se tocan en ning\xFAn di\xE1logo: son lo que ES ese lugar, y la \xFAnica forma de cambiarlos es irte a otro sitio."}],consejo:"Mira la ficha del sitio en el di\xE1logo de partida \u2014el bot\xF3n de ayuda al lado del desplegable\u2014 antes de elegir. El desplegable los agrupa por continente: Europa, \xC1frica, Am\xE9rica, Asia y Ocean\xEDa. Un fiordo y un Amazonas se juegan tan distinto como dos especies.",palabras:["sitio","escenario","clima","latitud","altitud","lugar","mapa","oasis","taiga","fiordo","continente"]},en:{titulo:"The place",subtitulo:"Where you play decides the year you get",resumen:"Every scenario is a spot on the globe, with its own climate and latitude. You do not pick them separately: you pick the place and the place brings them. That is where the cold, the heat and \u2014 what almost nobody looks at \u2014 the hours of daylight in each season come from.",bloques:[{titulo:"Seven climates",texto:"The Mediterranean one is the old default. The OCEANIC barely freezes and has the mildest year; the CONTINENTAL freezes by day in winter and scorches in summer. The DESERT stands out not for its heat but for the twenty-degree gap between noon and dawn, which is why it freezes at night after a mild day. The TROPICAL is warm all year and never freezes; its nights cool little where the air is soaked or the sea is near and up to sixteen degrees in the dry season of dry places, and its winter shows more the further from the equator. The EQUATORIAL has no year at all: its four seasons look alike. And the HIGH MOUNTAIN has the harshest winter of all \u2014down to five below zero by day and ten below before dawn, the only climate that drops past five below\u2014 with a short but genuine summer: it is the one place where the whole year is a race to reach the good weather with your colony still standing."},{titulo:"Latitude rules the light",texto:"The further from the equator, the wider summer and winter drift apart. In the Amazon the day lasts twelve hours all three hundred and sixty-five of them; in the fjord it runs from five and a half hours at midwinter to eighteen and a half at midsummer. That changes the whole match: how long you can forage, how much night you must sit through and how many hours the spider hunts."},{titulo:"Height cools",texto:"Every thousand metres take six and a half degrees off, exactly as in the real world. That is why the savannah, at nine hundred metres, plays six degrees below what its tropics promise \u2014 and still never freezes \u2014 while the prairie, at five hundred, frosts before dawn three seasons out of four. Climate, height and latitude are touched in no dialog at all: they are what that place IS, and the only way to change them is to go somewhere else."}],consejo:"Read the place card in the match dialog \u2014 the help button next to the dropdown \u2014 before you choose. The dropdown groups them by continent: Europe, Africa, America, Asia and Oceania. A fjord and an Amazon play as differently as two species.",palabras:["place","scenario","climate","latitude","altitude","location","map","oasis","taiga","fjord","continent"]}},[{etiqueta:e("Sitios","Places"),valor:a("Veintis\xE9is: cinco por continente, seis en \xC1frica","Twenty-six: five per continent, six in Africa")},{etiqueta:e("Climas","Climates"),valor:a("Siete, y los siete en uso","Seven, all seven in use")},{etiqueta:e("El d\xEDa m\xE1s largo","Longest day"),valor:a("18,5 h en el fiordo","18.5 h in the fjord")},{etiqueta:e("El m\xE1s corto","Shortest"),valor:a("5,5 h, el mismo sitio en invierno","5.5 h, same place in winter")},{etiqueta:e("Sin estaciones","No seasons"),valor:a("Amazonas: 12 h todo el a\xF1o","Amazon: 12 h all year")}],["mundo/clima","mundo/invierno","mundo/noche"]),o("mediterraneo","idioma",{es:{titulo:"El Mediterr\xE1neo",subtitulo:"La costa de siempre: verano seco, invierno suave",resumen:"El sitio por defecto. Una costa del Tirreno a 38\xB0 norte y 30 metros sobre el mar, con el clima mediterr\xE1neo de toda la vida: verano seco y caluroso, e invierno corto que hiela de madrugada. Colinas de hasta trece niveles y la comida en corros redondos, como olivos y pinos sueltos.",bloques:[{titulo:"El a\xF1o",texto:"Primavera a 17 grados de d\xEDa y 6 de madrugada; verano a 31 con noches de 20; oto\xF1o a 15 y 4; invierno a 1 grado al mediod\xEDa y madrugadas de cinco bajo cero. Desde media primavera hasta el final del verano no hiela ni de d\xEDa ni de noche: los primeros d\xEDas de la primavera todav\xEDa escarchan de madrugada, y en la segunda mitad del oto\xF1o vuelve a hacerlo. Es el sitio m\xE1s equilibrado del cat\xE1logo, y por eso es el que sale al abrir el juego."},{titulo:"El suelo",texto:"Sin piedras: el suelo lo hacen las colinas, de hasta trece niveles con rampas de uno, y la flora en manchas redondas regulares, cada una un pozo de comida sin halo alrededor. No hay pozas ni agua fija: la lluvia, que cae de oto\xF1o a primavera, encharca los huecos y se va con el sol. Hay que encontrar los corros y qued\xE1rselos: entre dos el suelo est\xE1 limpio, con una hierba que solo frena algo donde espesa."},{titulo:"La luz y la noche",texto:"El d\xEDa va de 9,4 horas en pleno invierno a 14,6 en pleno verano. De noche cazan la ara\xF1a de siempre y el escorpi\xF3n, que pica con la cola; la ara\xF1a errante no llega hasta aqu\xED."}],consejo:"Es el sitio para aprender: nada aprieta demasiado. Aprovecha la primavera para levantar el segundo hormiguero al lado de un corro de flora y ten la despensa llena antes del invierno, que corto pero hiela.",palabras:["mediterr\xE1neo","mediterraneo","costa","olivos","pinos","sitio","europa","por defecto"]},en:{titulo:"The Mediterranean",subtitulo:"The familiar coast: dry summer, mild winter",resumen:"The default place. A Tyrrhenian coast at 38\xB0 north and 30 metres above the sea, with the Mediterranean climate the game was built on: a dry, hot summer and a short winter that freezes before dawn. Hills up to thirteen levels high, and food in regular round patches, like scattered olive trees and pines.",bloques:[{titulo:"The year",texto:"Spring at 17 degrees by day and 6 before dawn; summer at 31 with nights of 20; autumn at 15 and 4; winter at 1 degree at noon with dawns of five below zero. From mid-spring to the end of summer it never freezes, day or night: the first days of spring still frost before dawn, and in the second half of autumn it does again. It is the most balanced place in the catalogue, which is why it is the one the game opens on."},{titulo:"The ground",texto:"No stones: the ground is made by the hills, up to thirteen levels with one-level ramps, and by the flora in regular round patches, each one a well of food with no halo around it. There are no pools or standing water: the rain, which falls from autumn to spring, fills the hollows and the sun takes it away. You have to find the patches and hold them: between two of them the ground is clean, with grass that only slows you a little where it thickens."},{titulo:"Light and night",texto:"The day runs from 9.4 hours at midwinter to 14.6 at midsummer. At night the usual spider and the scorpion, which stings with its tail, go hunting; the wandering spider does not reach this far."}],consejo:"This is the place to learn: nothing squeezes too hard. Use spring to raise the second anthill next to a patch of flora, and have the larder full before winter, which is short but does freeze.",palabras:["mediterranean","coast","olive","pine","place","europe","default"]}},[{etiqueta:e("D\xF3nde","Where"),valor:a("Europa \xB7 38\xB0 norte \xB7 30 m","Europe \xB7 38\xB0 north \xB7 30 m")},{etiqueta:e("Clima","Climate"),valor:a("Mediterr\xE1neo","Mediterranean")},{etiqueta:e("Verano / invierno","Summer / winter"),valor:a("31 \xB0C de d\xEDa \xB7 1 \xB0C de d\xEDa y \u22125 de madrugada","31 \xB0C by day \xB7 1 \xB0C by day and \u22125 before dawn")},{etiqueta:e("El d\xEDa","The day"),valor:a("De 9,4 a 14,6 h","From 9.4 to 14.6 h")},{etiqueta:e("Relieve","Relief"),valor:a("13 niveles, sin pozas","13 levels, no pools")},{etiqueta:e("Flora","Flora"),valor:a("0,7\xD7, corros redondos de radio 3,4","0.7\xD7, round patches of radius 3.4")},n("mediterraneo")],["mundo/sitio","mundo/clima","mundo/invierno"]),o("pradera","idioma",{es:{titulo:"La Pradera",subtitulo:"Las Grandes Llanuras: abierta, y con un invierno de verdad",resumen:"Norteam\xE9rica, 41\xB0 norte y 500 metros de altura en el interior del continente. Clima continental: el verano achicharra y el invierno hiela tambi\xE9n al mediod\xEDa. Es campo abierto: colinas suaves sin una piedra, y la hierba crece en corros redondos grandes.",bloques:[{titulo:"El a\xF1o",texto:"Primavera a 15 grados de d\xEDa pero cinco bajo cero de madrugada; verano a 34 con noches de 14; oto\xF1o a 12 y madrugadas heladas; invierno a cinco bajo cero de d\xEDa y de noche. Solo el verano se libra de la escarcha, y por poco \u2014sus \xFAltimos d\xEDas ya escarchan de madrugada\u2014, as\xED que el a\xF1o se juega a llegar a \xE9l con la colonia entera y a llenar la despensa antes de que se acabe. Y en invierno NIEVA: la nieve cuaja y frena el paso, y los charcos se hielan."},{titulo:"El suelo",texto:"Sin una piedra y con colinas de hasta doce niveles, todas de rampa suave: se camina a cualquier parte y se ve venir a todo el mundo. No hay pozas ni agua fija. La comida crece en manchas redondas regulares, m\xE1s grandes que los olivos del Mediterr\xE1neo, y entre ellas el suelo est\xE1 raso. Sin muros donde parapetarse, quien llega antes al corro de al lado gana."},{titulo:"La luz y la noche",texto:"El d\xEDa va de 9 horas en pleno invierno a 15 en pleno verano: el verano da mucho rato para forrajear y el invierno casi nada. De noche caza la ara\xF1a de siempre."}],consejo:"Sin piedras que cierren nada, la carrera es por los corros de hierba, no por los pasos. Expande en verano, cuando la noche no hiela, y no dejes columnas fuera al caer el oto\xF1o: la madrugada ya escarcha.",palabras:["pradera","llanura","continental","hierba","sitio","am\xE9rica","norteam\xE9rica"]},en:{titulo:"The Prairie",subtitulo:"The Great Plains: open, with a real winter",resumen:"North America, 41\xB0 north and 500 metres up in the middle of the continent. Continental climate: summer scorches and winter freezes even at noon. It is open country: gentle hills without a single stone, and the grass grows in big round patches.",bloques:[{titulo:"The year",texto:"Spring at 15 degrees by day but five below zero before dawn; summer at 34 with nights of 14; autumn at 12 with frosty dawns; winter at five below by day and by night. Only summer escapes the frost, and barely \u2014 its last days already frost before dawn \u2014, so the year is a race to reach it with the whole colony and to fill the larder before it ends. And in winter it SNOWS: the snow settles and slows the march, and the puddles freeze."},{titulo:"The ground",texto:"Not a single stone, and hills up to twelve levels high, all of them on gentle ramps: you walk to anywhere and see everyone coming. There are no pools or standing water. Food grows in regular round patches, larger than the Mediterranean olive groves, and between them the ground is bare. With no walls to hide behind, whoever reaches the next patch first wins it."},{titulo:"Light and night",texto:"The day runs from 9 hours at midwinter to 15 at midsummer: summer gives plenty of foraging time and winter almost none. At night the usual spider hunts."}],consejo:"With no stones to close anything off, the race is for the grass patches, not for the passes. Expand in summer, when the night does not freeze, and leave no columns outside when autumn falls: the dawns already frost.",palabras:["prairie","plains","continental","grass","place","america","north america"]}},[{etiqueta:e("D\xF3nde","Where"),valor:a("Am\xE9rica \xB7 41\xB0 norte \xB7 500 m","America \xB7 41\xB0 north \xB7 500 m")},{etiqueta:e("Clima","Climate"),valor:a("Continental","Continental")},{etiqueta:e("Verano / invierno","Summer / winter"),valor:a("34 \xB0C de d\xEDa \xB7 \u22125 \xB0C de d\xEDa y de noche","34 \xB0C by day \xB7 \u22125 \xB0C day and night")},{etiqueta:e("El d\xEDa","The day"),valor:a("De 9 a 15 h","From 9 to 15 h")},{etiqueta:e("Relieve","Relief"),valor:a("12 niveles, sin pozas","12 levels, no pools")},{etiqueta:e("Flora","Flora"),valor:a("0,8\xD7, corros redondos de radio 3,8","0.8\xD7, round patches of radius 3.8")},{etiqueta:e("En invierno","In winter"),valor:a("Nieva; los charcos se hielan","It snows; puddles freeze")},n("pradera")],["mundo/sitio","mundo/invierno","mundo/clima"]),o("monzon","idioma",{es:{titulo:"El Monz\xF3n",subtitulo:"El sudeste asi\xE1tico: h\xFAmedo, cerrado y sin helada",resumen:"La casa de la tejedora. El bajo Mekong, 12\xB0 norte y 50 metros sobre el mar: clima tropical, c\xE1lido todo el a\xF1o y sin una sola escarcha, con la vegetaci\xF3n m\xE1s espesa del cat\xE1logo despu\xE9s del Amazonas. Colinas, ocho pozas que el monz\xF3n llena y la comida en manchas grandes por todas partes.",bloques:[{titulo:"El a\xF1o",texto:"Primavera a 33 grados de d\xEDa y 24 de madrugada; verano a 35 y 26; oto\xF1o a 31 y 21; invierno a 28 de d\xEDa y 18 de madrugada. Las cuatro estaciones se trabajan enteras: aqu\xED el invierno solo se nota en que brota menos, en que la noche es un poco m\xE1s larga y m\xE1s fresca y en que apenas llueve. El verano, en cambio, es el monz\xF3n: el agua empapa el mapa."},{titulo:"El suelo",texto:"Sin piedras: colinas de hasta trece niveles y OCHO POZAS, las hondonadas donde el agua se junta primero. Con las lluvias del monz\xF3n se anegan, y un hormiguero fundado abajo puede ahogarse. La hierba es espesa y frena hasta un cuarenta por ciento, y la flora es densa (1,4 veces la de siempre) y en manchas anchas: hay comida por todas partes, y por eso hay vecinos por todas partes."},{titulo:"La luz y la noche",texto:"El d\xEDa apenas cambia: de 11,3 horas en invierno a 12,7 en verano. La noche es de calor y la m\xE1s poblada del cat\xE1logo: la ara\xF1a de siempre, la errante, el escorpi\xF3n y la escolopendra, y cada noche se echa a suertes cu\xE1l sale a cazar a la hormiga que se queda sola y lejos."}],consejo:"Sin invierno que temer, lo que manda es el agua: cada poza es una despensa en seco y una trampa en la crecida. La tejedora est\xE1 en casa \u2014anida en alto y con el nido anegado aguanta el doble que las dem\xE1s\u2014 y las otras tienen que elegir entre comer abajo y dormir arriba.",palabras:["monz\xF3n","monzon","tropical","mekong","tejedora","oecophylla","sitio","asia","sudeste asi\xE1tico"]},en:{titulo:"The Monsoon",subtitulo:"Southeast Asia: humid, closed in and frost-free",resumen:"Home of the weaver ant. The lower Mekong, 12\xB0 north and 50 metres above the sea: tropical climate, warm all year without a single frost, and the thickest vegetation in the catalogue after the Amazon. Hills, eight pools the monsoon fills, and food in big patches everywhere.",bloques:[{titulo:"The year",texto:"Spring at 33 degrees by day and 24 before dawn; summer at 35 and 26; autumn at 31 and 21; winter at 28 by day and 18 before dawn. All four seasons can be worked in full: here winter shows only as fewer sprouts, a slightly longer and cooler night and hardly any rain. Summer, on the other hand, is the monsoon: water soaks the map."},{titulo:"The ground",texto:"No stones: hills up to thirteen levels high and EIGHT POOLS, the hollows where water gathers first. With the monsoon rains they flood, and an anthill founded down there can drown. The grass is thick and slows ants by up to forty percent, and the flora is dense (1.4 times the usual) and in wide patches: there is food everywhere, which is why there are neighbours everywhere."},{titulo:"Light and night",texto:"The day barely changes: from 11.3 hours in winter to 12.7 in summer. Nights are warm and the busiest in the catalogue: the usual spider, the wandering one, the scorpion and the centipede, and each night a draw decides which one goes after the ant left far and alone."}],consejo:"With no winter to fear, water is what rules: every pool is a larder when dry and a trap in the flood. The weaver is at home here \u2014 she nests high and, with her nest flooded, lasts twice as long as the rest \u2014 and everyone else has to choose between eating low and sleeping high.",palabras:["monsoon","tropical","mekong","weaver","oecophylla","place","asia","southeast asia"]}},[{etiqueta:e("D\xF3nde","Where"),valor:a("Asia \xB7 12\xB0 norte \xB7 50 m","Asia \xB7 12\xB0 north \xB7 50 m")},{etiqueta:e("Clima","Climate"),valor:a("Tropical","Tropical")},{etiqueta:e("Verano / invierno","Summer / winter"),valor:a("35 \xB0C de d\xEDa y 26 de noche \xB7 28 \xB0C de d\xEDa y 18 de noche","35 \xB0C by day and 26 by night \xB7 28 \xB0C by day and 18 by night")},{etiqueta:e("El d\xEDa","The day"),valor:a("De 11,3 a 12,7 h","From 11.3 to 12.7 h")},{etiqueta:e("Relieve","Relief"),valor:a("13 niveles y 8 pozas que se anegan","13 levels and 8 pools that flood")},{etiqueta:e("Flora","Flora"),valor:a("1,4\xD7, manchas de radio 4,5","1.4\xD7, patches of radius 4.5")},n("monzon"),{etiqueta:e("Su especie","Its species"),valor:a("La tejedora (Oecophylla)","The weaver ant (Oecophylla)")}],["especies/tejedora","mundo/sitio","mundo/noche","fauna/arana-errante"]),o("outback","idioma",{es:{titulo:"El Outback",subtitulo:"El centro de Australia: el d\xEDa quema y la noche se lo lleva",resumen:"La casa de la bulldog. El interior australiano, 25\xB0 sur y 400 metros de altura: clima des\xE9rtico, con el salto de temperatura m\xE1s grande del cat\xE1logo entre el mediod\xEDa y el amanecer. Campo abierto sin piedras y una flora rala en manchas medianas: lejos de casa hay poco que comer.",bloques:[{titulo:"El a\xF1o",texto:"Primavera y oto\xF1o a 25 grados de d\xEDa y 4 de madrugada; verano a 35 con noches de 17; invierno a 13 al mediod\xEDa y cinco bajo cero antes del alba. Solo el verano est\xE1 libre de escarcha: el resto del a\xF1o la madrugada muerde aunque el d\xEDa haya sido templado, y ese es el rasgo del desierto. Est\xE1 en el hemisferio sur, pero el verano del juego es la estaci\xF3n c\xE1lida del sitio, as\xED que el a\xF1o se cuenta igual."},{titulo:"El suelo",texto:"Sin piedras: campo abierto con colinas de hasta doce niveles, sin pozas y con una hierba seca que apenas frena. La flora es rala \u2014menos de la mitad de plantas que en la costa\u2014 en manchas medianas y separadas: cada una vale mucho y todo el mundo la ve desde lejos."},{titulo:"La luz y la noche",texto:"El d\xEDa va de 10,4 horas en pleno invierno a 13,6 en pleno verano. De noche salen las dos ara\xF1as y el escorpi\xF3n; en un campo tan abierto encuentran pronto a la que se rezaga."}],consejo:"La bulldog est\xE1 en casa: ve lejos, corre y pega, que es lo que pide un campo abierto con la comida a trechos. Con cualquier otra especie, guarece a la colonia antes del amanecer fuera del verano, porque la helada de madrugada llega despu\xE9s de un d\xEDa de 25 grados y no se ve venir.",palabras:["outback","australia","desierto","des\xE9rtico","bulldog","myrmecia","sitio","ocean\xEDa","sur"]},en:{titulo:"The Outback",subtitulo:"Central Australia: the day burns and the night takes it all back",resumen:"Home of the bulldog ant. The Australian interior, 25\xB0 south and 400 metres up: desert climate, with the biggest swing in the catalogue between noon and dawn. Open country without stones and thin flora in medium patches: far from home there is little to eat.",bloques:[{titulo:"The year",texto:"Spring and autumn at 25 degrees by day and 4 before dawn; summer at 35 with nights of 17; winter at 13 at noon and five below before daybreak. Only summer is free of frost: the rest of the year the dawn bites even after a mild day, and that is what makes a desert. It sits in the southern hemisphere, but the game\u2019s summer is the warm season of the place, so the year is counted the same way."},{titulo:"The ground",texto:"No stones: open country with hills up to twelve levels high, no pools and a dry grass that hardly slows anyone. Flora is thin \u2014 under half the plants of the coast \u2014 in medium, scattered patches: each one is worth a lot and everyone can see it from afar."},{titulo:"Light and night",texto:"The day runs from 10.4 hours at midwinter to 13.6 at midsummer. At night both spiders and the scorpion come out; in country this open they soon find whoever lags behind."}],consejo:"The bulldog is at home: she sees far, runs and hits, which is what open country with food in stretches asks for. With any other species, shelter the colony before dawn outside summer, because the pre-dawn frost comes after a 25-degree day and cannot be seen coming.",palabras:["outback","australia","desert","bulldog","myrmecia","place","oceania","south"]}},[{etiqueta:e("D\xF3nde","Where"),valor:a("Ocean\xEDa \xB7 25\xB0 sur \xB7 400 m","Oceania \xB7 25\xB0 south \xB7 400 m")},{etiqueta:e("Clima","Climate"),valor:a("Des\xE9rtico","Desert")},{etiqueta:e("Verano / invierno","Summer / winter"),valor:a("35 \xB0C de d\xEDa \xB7 13 \xB0C de d\xEDa y \u22125 de madrugada","35 \xB0C by day \xB7 13 \xB0C by day and \u22125 before dawn")},{etiqueta:e("El d\xEDa","The day"),valor:a("De 10,4 a 13,6 h","From 10.4 to 13.6 h")},{etiqueta:e("Relieve","Relief"),valor:a("12 niveles, sin pozas","12 levels, no pools")},{etiqueta:e("Flora","Flora"),valor:a("0,45\xD7, manchas de radio 3,2","0.45\xD7, patches of radius 3.2")},n("outback"),{etiqueta:e("Su especie","Its species"),valor:a("La bulldog (Myrmecia)","The bulldog ant (Myrmecia)")}],["especies/bulldog","mundo/sitio","mundo/noche","fauna/arana-errante"]),o("caribe","idioma",{es:{titulo:"El Caribe",subtitulo:"Medio mapa es mar: una isla madre y hasta seis islas vac\xEDas",resumen:"Am\xE9rica, 18\xB0 norte, a veinte metros del mar. Es el \xFAnico sitio del cat\xE1logo donde el suelo NO es de una pieza: casi la mitad del mapa es agua, y la tierra son hasta siete islas. Todas las colonias nacen en la isla madre, la del centro; las dem\xE1s \u2014hasta seis\u2014 est\xE1n vac\xEDas, tienen comida y solo se llega a ellas volando.",bloques:[{titulo:"La isla madre",texto:"La grande, en el centro del mapa, y ah\xED nacen TODAS las colonias, sin excepci\xF3n. Las puertas est\xE1n m\xE1s juntas que en cualquier otro sitio \u2014el c\xEDrculo se encoge para que quepan en la isla\u2014 y ninguna nace a menos de siete casillas del agua, que es lo que mide el cono de un hormiguero de mil hormigas: por muy grande que se haga, un hormiguero nunca toca el mar. La guerra del Caribe se pelea aqu\xED."},{titulo:"Las otras islas",texto:"Hasta seis \u2014si alguna no cabe, salen menos\u2014, de siete a once casillas de radio en un mapa de 96 (y a escala en los mayores), separadas de la madre y entre s\xED por brazos de mar de tres a ocho casillas. Nacen vac\xEDas, pero NUNCA sin comida: cada una lleva su planta. Son la retaguardia \u2014 se llega volando, y solo volando: la reina en vuelo nupcial funda all\xED."},{titulo:"El clima",texto:"Tropical de verdad: no hiela jam\xE1s. Treinta y tres grados al mediod\xEDa en primavera, treinta y cinco en verano, veintinueve en oto\xF1o y veinticinco en invierno, con madrugadas que no bajan de diecisiete. El d\xEDa casi no se mueve en todo el a\xF1o: de once a trece horas de luz. Aqu\xED no manda el reloj, manda el mar."}],consejo:"Piensa d\xF3nde est\xE1 tu orilla antes de expandirte. Una reina que vuela a una isla vac\xEDa tiene comida y nadie que la ataque a pie, pero tambi\xE9n se queda SIN REFUERZOS para siempre: al mar no se le cruza a pie, as\xED que lo que mandes con ella es todo lo que va a tener.",palabras:["caribe","archipi\xE9lago","isla","islas","mar","agua","tropical","am\xE9rica","cortadora"]},en:{titulo:"The Caribbean",subtitulo:"Half the map is sea: one mother island and up to six empty ones",resumen:"America, 18\xB0 north, twenty metres above the sea. It is the only place in the catalogue where the ground is NOT in one piece: almost half the map is water, and the land is up to seven islands. Every colony is born on the mother island, the one in the middle; the rest \u2014 up to six \u2014 are empty, they have food, and the only way to reach them is by flying.",bloques:[{titulo:"The mother island",texto:"The big one, in the middle of the map, and EVERY colony is born there, without exception. The doors sit closer together than anywhere else \u2014 the circle shrinks so they all fit on the island \u2014 and none is born within seven cells of the water, which is the reach of the mound of a thousand-ant nest: however big it grows, a nest never touches the sea. The Caribbean war is fought here."},{titulo:"The other islands",texto:"Up to six \u2014 if one does not fit, fewer come out \u2014, seven to eleven cells in radius on a 96 map (and to scale on bigger ones), kept apart from the mother and from each other by arms of sea three to eight cells wide. They are born empty, but NEVER without food: each one carries its own plant. They are the rear \u2014 reached by flying, and only by flying: a queen on her nuptial flight founds there."},{titulo:"The climate",texto:"Properly tropical: it never freezes. Thirty-three degrees at noon in spring, thirty-five in summer, twenty-nine in autumn and twenty-five in winter, with dawns that never drop below seventeen. The day hardly moves all year: eleven to thirteen hours of light. Here the clock does not rule, the sea does."}],consejo:"Think about where your shore is before you expand. A queen who flies to an empty island has food and nobody who can reach her on foot, but she also has NO reinforcements, ever: the sea cannot be crossed on foot, so whatever you send with her is all she will ever have.",palabras:["caribbean","archipelago","island","islands","sea","water","tropical","america","leafcutter"]}},[{etiqueta:e("D\xF3nde","Where"),valor:a("Am\xE9rica \xB7 18\xB0 norte \xB7 20 m","America \xB7 18\xB0 north \xB7 20 m")},{etiqueta:e("Clima","Climate"),valor:a("Tropical: no hiela nunca","Tropical: it never freezes")},{etiqueta:e("Verano / invierno","Summer / winter"),valor:a("35 \xB0C de d\xEDa y 29 de noche \xB7 25 \xB0C de d\xEDa y 17 de noche","35 \xB0C by day and 29 by night \xB7 25 \xB0C by day and 17 by night")},{etiqueta:e("El d\xEDa","The day"),valor:a("De 10,9 a 13,1 h","From 10.9 to 13.1 h")},{etiqueta:e("El mar","The sea"),valor:a("Casi la mitad del mapa","Almost half the map")},{etiqueta:e("Islas","Islands"),valor:a("Hasta 7: la madre y hasta seis vac\xEDas","Up to 7: the mother and up to six empty")},{etiqueta:e("Relieve","Relief"),valor:a("12 niveles, sin pozas","12 levels, no pools")},{etiqueta:e("Flora","Flora"),valor:a("1,3\xD7, manchas de radio 4,2","1.3\xD7, patches of radius 4.2")},n("caribe"),{etiqueta:e("Su especie","Its species"),valor:a("La cortadora (Atta)","The leafcutter ant (Atta)")}],["especies/cortadora","mundo/sitio","mundo/agua"]),o("fiordo","idioma",{es:{titulo:"El Fiordo",subtitulo:"La costa noruega: el a\xF1o m\xE1s suave y los d\xEDas m\xE1s extremos",resumen:"Europa, 60\xB0 norte, a diez metros del agua. Clima oce\xE1nico: el mar amortigua el a\xF1o entero, as\xED que ni el verano quema ni el invierno baja de cero. Lo que manda aqu\xED es la luz, con el d\xEDa m\xE1s largo del cat\xE1logo en verano y el m\xE1s corto en invierno. En el mapa hay tres lagunas, una de ellas con un islote, entre colinas sin piedras y con la flora de siempre.",bloques:[{titulo:"El a\xF1o",texto:"Primavera a 17 grados de d\xEDa y 10 de madrugada; verano a 25 con noches de 18; oto\xF1o a 16 y 9; invierno a 7 al mediod\xEDa y 1 grado antes del alba. Es el a\xF1o m\xE1s suave del cat\xE1logo: la \xFAnica escarcha es la de las madrugadas de invierno, lenta y sin bajar de cero, y ninguna estaci\xF3n se pierde entera."},{titulo:"El suelo",texto:"Sin piedras: colinas de hasta doce niveles y TRES LAGUNAS que no se secan nunca, una con un islote al que solo se llega volando. Se rodean por la orilla, y junto a ellas la comida brota m\xE1s y m\xE1s gorda. El sitio es h\xFAmedo y la hierba espesa frena hasta un cuarenta por ciento. La flora es la de siempre, ni densa ni rala, en manchas medianas. Aun as\xED, lo que distingue al sitio no es el suelo: es el cielo."},{titulo:"La luz y la noche",texto:"El d\xEDa va de 5,5 horas en pleno invierno a 18,5 en pleno verano, los dos extremos del cat\xE1logo. En verano casi no hay noche que aguantar; en invierno la ara\xF1a de siempre caza dieciocho horas seguidas y el poco sol que hay apenas caldea."}],consejo:"Aqu\xED el reloj es el sitio. Forrajea a destajo en el verano de dieciocho horas y ten la despensa a tope al entrar el oto\xF1o: el invierno no mata de fr\xEDo, mata de noche, con seis horas de luz y la ara\xF1a el resto.",palabras:["fiordo","oce\xE1nico","costero","noruega","luz","sitio","europa","norte"]},en:{titulo:"The Fjord",subtitulo:"The Norwegian coast: the mildest year and the most extreme days",resumen:"Europe, 60\xB0 north, ten metres from the water. Oceanic climate: the sea cushions the whole year, so summer never burns and winter never drops below zero. What rules here is the light, with the longest day in the catalogue in summer and the shortest in winter. The map holds three lakes, one of them with an islet, among stoneless hills and the usual flora.",bloques:[{titulo:"The year",texto:"Spring at 17 degrees by day and 10 before dawn; summer at 25 with nights of 18; autumn at 16 and 9; winter at 7 at noon and 1 degree before daybreak. It is the mildest year in the catalogue: the only frost is that of winter dawns, slow and never below zero, and no season is lost entirely."},{titulo:"The ground",texto:"No stones: hills up to twelve levels high and THREE LAKES that never dry up, one with an islet that can only be reached by flying. You go round them by the shore, and next to them food sprouts more often and richer. The place is damp and the thick grass slows ants by up to forty percent. The flora is the usual one, neither dense nor thin, in medium patches. Even so, what sets the place apart is not its ground: it is its sky."},{titulo:"Light and night",texto:"The day runs from 5.5 hours at midwinter to 18.5 at midsummer, the two extremes of the catalogue. In summer there is hardly any night to sit through; in winter the usual spider hunts for eighteen hours straight and what little sun there is barely warms."}],consejo:"Here the clock is the place. Forage flat out through the eighteen-hour summer and have the larder full as autumn comes in: winter does not kill with cold, it kills with night, six hours of light and the spider for the rest.",palabras:["fjord","oceanic","coastal","norway","light","place","europe","north"]}},[{etiqueta:e("D\xF3nde","Where"),valor:a("Europa \xB7 60\xB0 norte \xB7 10 m","Europe \xB7 60\xB0 north \xB7 10 m")},{etiqueta:e("Clima","Climate"),valor:a("Oce\xE1nico","Oceanic")},{etiqueta:e("Verano / invierno","Summer / winter"),valor:a("25 \xB0C de d\xEDa \xB7 7 \xB0C de d\xEDa y 1 de madrugada","25 \xB0C by day \xB7 7 \xB0C by day and 1 before dawn")},{etiqueta:e("El d\xEDa","The day"),valor:a("De 5,5 a 18,5 h","From 5.5 to 18.5 h")},{etiqueta:e("Agua","Water"),valor:a("Tres lagunas, una con islote","Three lakes, one with an islet")},{etiqueta:e("Relieve","Relief"),valor:a("12 niveles, sin pozas","12 levels, no pools")},{etiqueta:e("Flora","Flora"),valor:a("1\xD7, manchas de radio 3,6","1\xD7, patches of radius 3.6")},n("fiordo")],["mundo/sitio","mundo/clima","mundo/noche"]),o("cumbre","idioma",{es:{titulo:"La Cumbre",subtitulo:"Los Alpes: el invierno m\xE1s duro y un verano corto de verdad",resumen:"Europa, 46\xB0 norte, alta monta\xF1a. El fr\xEDo de la altura viene en el propio clima, y los 400 metros del sitio son el matiz. Hiela todas las noches del a\xF1o menos las de verano, y en invierno tambi\xE9n al mediod\xEDa. Es de los sitios m\xE1s empinados del cat\xE1logo y de los que menos comida tienen: se juega por las laderas.",bloques:[{titulo:"El a\xF1o",texto:"Primavera a 10 grados de d\xEDa y tres bajo cero de madrugada; verano a 24 con noches de 11; oto\xF1o a 11 y dos bajo cero; invierno a cinco bajo cero de d\xEDa y diez de madrugada, el fr\xEDo m\xE1s duro del juego. Solo el verano est\xE1 libre de escarcha, y en invierno la helada no levanta a ninguna hora. Y NIEVA: la nieve cuaja, frena el paso hasta un sesenta por ciento y los charcos se hielan. El a\xF1o entero se juega a llegar al buen tiempo con la colonia en pie y a aprovecharlo."},{titulo:"El suelo",texto:"Sin piedras: trece niveles, el tope del juego, en laderas empinadas que obligan a subir y bajar a cada paso, y sin pozas. La flora es de las m\xE1s escasas de todos los sitios \u2014un tercio de las plantas de siempre\u2014 en manchas peque\xF1as: cada corro vale una estaci\xF3n."},{titulo:"La luz y la noche",texto:"El d\xEDa va de 8,4 horas en pleno invierno a 15,6 en pleno verano. De noche caza la ara\xF1a de siempre, y con la helada encima la que vuelve tarde ya no llega: el fr\xEDo la deja a la d\xE9cima parte de su paso."}],consejo:"Cava hondo y pronto: el verano es la \xFAnica estaci\xF3n para salir lejos, y lo que no est\xE9 en la despensa al caer el oto\xF1o ya no llega. Y pelea desde arriba: en un sitio de laderas, la que pisa m\xE1s alto muerde m\xE1s fuerte.",palabras:["cumbre","monta\xF1a","alta monta\xF1a","alpes","nieve","sitio","europa","fr\xEDo"]},en:{titulo:"The Summit",subtitulo:"The Alps: the harshest winter and a short but real summer",resumen:"Europe, 46\xB0 north, high mountain. The cold of altitude comes built into the climate itself, and the 400 metres of the place are the nuance. It frosts every night of the year except the summer ones, and in winter at noon as well. It is among the steepest places in the catalogue and among those with the least food: you play on the slopes.",bloques:[{titulo:"The year",texto:"Spring at 10 degrees by day and three below zero before dawn; summer at 24 with nights of 11; autumn at 11 and two below; winter at five below by day and ten below before dawn, the hardest cold in the game. Only summer is free of frost, and in winter the freeze never lifts at any hour. And it SNOWS: the snow settles, slows the march by up to sixty percent and the puddles freeze. The whole year is a race to reach the good weather with the colony standing, and to make the most of it."},{titulo:"The ground",texto:"No stones: thirteen levels, the top in the game, on steep slopes that make you climb and drop at every step, and no pools. The flora is among the scarcest of any place \u2014 a third of the usual plants \u2014 in small patches: each one is worth a season."},{titulo:"Light and night",texto:"The day runs from 8.4 hours at midwinter to 15.6 at midsummer. At night the usual spider hunts, and with the freeze on top the one who comes home late never makes it: the cold cuts her to a tenth of her stride."}],consejo:"Dig deep and early: summer is the only season for ranging far, and whatever is not in the larder when autumn falls will never arrive. And fight from above: in a place of slopes, the ant standing higher bites harder.",palabras:["summit","mountain","high mountain","alps","snow","place","europe","cold"]}},[{etiqueta:e("D\xF3nde","Where"),valor:a("Europa \xB7 46\xB0 norte \xB7 400 m","Europe \xB7 46\xB0 north \xB7 400 m")},{etiqueta:e("Clima","Climate"),valor:a("Alta monta\xF1a","High mountain")},{etiqueta:e("Verano / invierno","Summer / winter"),valor:a("24 \xB0C de d\xEDa \xB7 \u22125 \xB0C de d\xEDa y \u221210 de madrugada","24 \xB0C by day \xB7 \u22125 \xB0C by day and \u221210 before dawn")},{etiqueta:e("El d\xEDa","The day"),valor:a("De 8,4 a 15,6 h","From 8.4 to 15.6 h")},{etiqueta:e("Relieve","Relief"),valor:a("13 niveles, empinados","13 levels, steep")},{etiqueta:e("Flora","Flora"),valor:a("0,35\xD7, manchas de radio 2,6","0.35\xD7, patches of radius 2.6")},{etiqueta:e("En invierno","In winter"),valor:a("Nieva; los charcos se hielan","It snows; puddles freeze")},n("cumbre")],["mundo/sitio","mundo/invierno","hormiguero/despensa"]),o("taiga","idioma",{es:{titulo:"La Taiga",subtitulo:"El bosque boreal: la casa de la roja, y el a\xF1o m\xE1s duro",resumen:"La casa de la roja. El bosque boreal a 58\xB0 norte y 250 metros: clima continental en el norte de verdad, con el verano en el tope del term\xF3metro y un invierno que hiela de d\xEDa y de noche con seis horas de luz. Colinas sin piedras y la comida en claros peque\xF1os y escasos.",bloques:[{titulo:"El a\xF1o",texto:"Primavera a 16 grados de d\xEDa y cuatro bajo cero de madrugada; verano a 35 con noches de 16; oto\xF1o a 14 y cinco bajo cero; invierno a cinco bajo cero a cualquier hora. Un a\xF1o de dos caras: el verano da calor y luz de sobra, y las otras tres estaciones escarchan de madrugada. En invierno NIEVA: la nieve cuaja y frena el paso, y los charcos se hielan. Junta el invierno continental con la noche larga del norte, y por eso es el sitio m\xE1s duro del cat\xE1logo."},{titulo:"El suelo",texto:"Sin piedras: colinas de hasta doce niveles, sin pozas, y suelo de bosque h\xFAmedo, con una hierba espesa que frena hasta un cuarenta por ciento. La flora es escasa, seis de cada diez plantas de las de siempre, en manchas cortas: los claros donde brota son pocos y todo el mundo los conoce."},{titulo:"La luz y la noche",texto:"El d\xEDa va de 6,1 horas en pleno invierno a 17,9 en pleno verano. De noche caza la ara\xF1a de siempre, y en invierno tiene dieciocho horas para hacerlo."}],consejo:"La roja est\xE1 en casa: levanta una colonia grande y dif\xEDcil de desalojar, que es lo que pide un sitio donde se pasa medio a\xF1o bajo techo. Con cualquier especie, el verano es la partida entera: expande, llena la despensa y vuelve dentro antes de que el oto\xF1o escarche.",palabras:["taiga","bosque","boreal","continental","roja","formica","sitio","europa","norte"]},en:{titulo:"The Taiga",subtitulo:"The boreal forest: home of the red wood ant, and the harshest year",resumen:"Home of the red wood ant. The boreal forest at 58\xB0 north and 250 metres: a continental climate in the true north, with summer at the top of the thermometer and a winter that freezes day and night on six hours of light. Stoneless hills and food in small, scarce clearings.",bloques:[{titulo:"The year",texto:"Spring at 16 degrees by day and four below zero before dawn; summer at 35 with nights of 16; autumn at 14 and five below; winter at five below at any hour. A two-faced year: summer gives heat and light to spare, and the other three seasons frost before dawn. In winter it SNOWS: the snow settles and slows the march, and the puddles freeze. Put the continental winter together with the long northern night, and that is why it is the harshest place in the catalogue."},{titulo:"The ground",texto:"No stones: hills up to twelve levels high, no pools, and damp forest floor, with a thick grass that slows ants by up to forty percent. The flora is scarce, six in ten of the usual plants, in short patches: the clearings where food sprouts are few and everyone knows them."},{titulo:"Light and night",texto:"The day runs from 6.1 hours at midwinter to 17.9 at midsummer. At night the usual spider hunts, and in winter it has eighteen hours to do so."}],consejo:"The red wood ant is at home: she raises a large colony that is hard to dislodge, which is what a place where half the year is spent indoors asks for. With any species, summer is the whole match: expand, fill the larder and get back inside before autumn frosts.",palabras:["taiga","forest","boreal","continental","red wood ant","formica","place","europe","north"]}},[{etiqueta:e("D\xF3nde","Where"),valor:a("Europa \xB7 58\xB0 norte \xB7 250 m","Europe \xB7 58\xB0 north \xB7 250 m")},{etiqueta:e("Clima","Climate"),valor:a("Continental","Continental")},{etiqueta:e("Verano / invierno","Summer / winter"),valor:a("35 \xB0C de d\xEDa \xB7 \u22125 \xB0C de d\xEDa y de noche","35 \xB0C by day \xB7 \u22125 \xB0C day and night")},{etiqueta:e("El d\xEDa","The day"),valor:a("De 6,1 a 17,9 h","From 6.1 to 17.9 h")},{etiqueta:e("Relieve","Relief"),valor:a("12 niveles, sin pozas","12 levels, no pools")},{etiqueta:e("Flora","Flora"),valor:a("0,6\xD7, manchas de radio 3","0.6\xD7, patches of radius 3")},{etiqueta:e("En invierno","In winter"),valor:a("Nieva; los charcos se hielan","It snows; puddles freeze")},n("taiga"),{etiqueta:e("Su especie","Its species"),valor:a("La roja (Formica rufa)","The red wood ant (Formica rufa)")}],["especies/roja","mundo/sitio","mundo/invierno","mundo/noche"]),o("sabana","idioma",{es:{titulo:"La Sabana",subtitulo:"El altiplano africano: campo abierto y sin helada",resumen:"\xC1frica, 10\xB0 norte y 900 metros de altura, en un altiplano tropical. La altura le quita seis grados al tr\xF3pico y aun as\xED no hiela nunca: el a\xF1o se nota en cu\xE1nto brota, no en el term\xF3metro. Es campo abierto de verdad \u2014sin piedras, comida rala y lejos\u2014 y se camina mucho para todo. Ninguna especie del juego tiene aqu\xED su casa.",bloques:[{titulo:"El a\xF1o",texto:"Primavera a 28 grados de d\xEDa y 12 de madrugada; verano a 29 y 18; oto\xF1o a 26 y 10; invierno a 24 al mediod\xEDa y 8 antes del alba. Sin una sola escarcha, pero con noches frescas: el aire seco no guarda el calor y de madrugada hace hasta diecis\xE9is grados menos que al mediod\xEDa. El invierno se nota en que brota un tercio y en que es seco; las lluvias llegan con el verano."},{titulo:"El suelo",texto:"Sin piedras: colinas de hasta trece niveles y CUATRO POZAS, las hondonadas donde se junta el agua primero; con las lluvias de verano se anegan, y un hormiguero fundado abajo puede ahogarse. La flora es rala, la mitad de plantas de las de siempre, en manchas medianas y separadas: entre corro y corro hay mucho suelo raso, y quien lo cruza se ve desde lejos."},{titulo:"La luz y la noche",texto:"El d\xEDa casi no cambia: de 11,4 horas en invierno a 12,6 en verano. De noche salen las dos ara\xF1as, la de siempre y la errante, y el escorpi\xF3n; en un campo as\xED de abierto encuentran pronto a la que se rezaga."}],consejo:"Sin invierno que temer ni muros que aprovechar, la partida es de distancias: levanta el segundo hormiguero al lado de un corro, no a media marcha de tres, y no dejes columnas largas fuera de noche.",palabras:["sabana","tropical","altiplano","hierba","campo abierto","sitio","\xE1frica"]},en:{titulo:"The Savannah",subtitulo:"The African plateau: open country with no frost",resumen:"Africa, 10\xB0 north and 900 metres up, on a tropical plateau. The altitude takes six degrees off the tropics and it still never freezes: the year shows in how much sprouts, not on the thermometer. It is truly open country \u2014 no stones, thin food and far apart \u2014 and you walk a long way for everything. No species in the game has its home here.",bloques:[{titulo:"The year",texto:"Spring at 28 degrees by day and 12 before dawn; summer at 29 and 18; autumn at 26 and 10; winter at 24 at noon and 8 before daybreak. Not a single frost, but cool nights: the dry air does not keep the heat and before dawn it is up to sixteen degrees cooler than at noon. Winter shows in a third of the sprouts and in being dry; the rains come with summer."},{titulo:"The ground",texto:"No stones: hills up to thirteen levels high and FOUR POOLS, the hollows where water gathers first; with the summer rains they flood, and an anthill founded down there can drown. The flora is thin, half the usual plants, in medium, scattered patches: between one patch and the next there is a lot of bare ground, and whoever crosses it can be seen from afar."},{titulo:"Light and night",texto:"The day barely changes: from 11.4 hours in winter to 12.6 in summer. At night both spiders come out, the usual one and the wandering one, and the scorpion; in country this open they soon find whoever lags behind."}],consejo:"With no winter to fear and no walls to lean on, the match is about distances: raise the second anthill next to a patch, not halfway between three, and leave no long columns outside at night.",palabras:["savannah","savanna","tropical","plateau","grass","open country","place","africa"]}},[{etiqueta:e("D\xF3nde","Where"),valor:a("\xC1frica \xB7 10\xB0 norte \xB7 900 m","Africa \xB7 10\xB0 north \xB7 900 m")},{etiqueta:e("Clima","Climate"),valor:a("Tropical","Tropical")},{etiqueta:e("Verano / invierno","Summer / winter"),valor:a("29 \xB0C de d\xEDa y 18 de noche \xB7 24 \xB0C de d\xEDa y 8 de noche","29 \xB0C by day and 18 by night \xB7 24 \xB0C by day and 8 by night")},{etiqueta:e("El d\xEDa","The day"),valor:a("De 11,4 a 12,6 h","From 11.4 to 12.6 h")},{etiqueta:e("Relieve","Relief"),valor:a("13 niveles y 4 pozas que se anegan","13 levels and 4 pools that flood")},{etiqueta:e("Flora","Flora"),valor:a("0,5\xD7, manchas de radio 3","0.5\xD7, patches of radius 3")},n("sabana")],["mundo/sitio","mundo/noche","fauna/arana-errante"]),o("oasis","idioma",{es:{titulo:"El Oasis",subtitulo:"El S\xE1hara: cuatro fuentes y nada alrededor",resumen:"\xC1frica, 27\xB0 norte y 300 metros, en pleno desierto. Clima des\xE9rtico: no lo define el calor sino el salto de veinte grados entre el mediod\xEDa y el amanecer, y por eso hiela de madrugada en invierno tras un d\xEDa de 13. Es el \xFAnico sitio donde la comida no brota a manchas por todo el mapa: casi toda cae junto a cuatro fuentes sim\xE9tricas. Ninguna especie del juego tiene aqu\xED su casa.",bloques:[{titulo:"El a\xF1o",texto:"Primavera y oto\xF1o a 25 grados de d\xEDa y 4 de madrugada; verano a 35 con noches de 18; invierno a 13 al mediod\xEDa y cinco bajo cero antes del alba. Solo el verano libra de la escarcha; el resto del a\xF1o la madrugada baja de los cinco grados aunque el d\xEDa haya sido templado, y eso es lo que hace desierto al desierto."},{titulo:"El suelo",texto:"Arena llana, sin una piedra ni una colina, y TRES CHARCAS de agua que no se secan, que se rodean por la orilla. Lo que cambia es la comida: el 85 por ciento de los brotes cae alrededor de cuatro fuentes sim\xE9tricas, lejos de todos los nidos y separadas entre s\xED, y el resto disperso por el mapa. No hay plantas escondidas que descubrir: se sabe d\xF3nde est\xE1 la comida, y todos van all\xED."},{titulo:"La luz y la noche",texto:"El d\xEDa va de 10,3 horas en pleno invierno a 13,7 en pleno verano. De noche salen la ara\xF1a de siempre y el escorpi\xF3n, y rondan los caminos de las fuentes, que es por donde va todo el mundo."}],consejo:"La partida es por las fuentes: quien se queda con dos come, y quien se queda sin ninguna se apaga. Levanta el segundo hormiguero pegado a una y defiende el camino, no el nido. Fuera del verano, todas dentro antes del alba.",palabras:["oasis","desierto","des\xE9rtico","s\xE1hara","fuentes","sitio","\xE1frica"]},en:{titulo:"The Oasis",subtitulo:"The Sahara: four springs and nothing around them",resumen:"Africa, 27\xB0 north and 300 metres, deep in the desert. Desert climate: it is defined not by heat but by the twenty-degree drop between noon and dawn, which is why it frosts before dawn in winter after a 13-degree day. It is the only place where food does not sprout in patches all over the map: almost all of it falls beside four symmetric springs. No species in the game has its home here.",bloques:[{titulo:"The year",texto:"Spring and autumn at 25 degrees by day and 4 before dawn; summer at 35 with nights of 18; winter at 13 at noon and five below before daybreak. Only summer is spared the frost; the rest of the year the dawn drops below five degrees even after a mild day, and that is what makes a desert a desert."},{titulo:"The ground",texto:"Flat sand, without a stone or a hill, and THREE PONDS of water that never dry up, which you go round by the shore. What changes is the food: 85 percent of the sprouts fall around four symmetric springs, far from every nest and apart from each other, and the rest is scattered across the map. There are no hidden plants to discover: everyone knows where the food is, and everyone goes there."},{titulo:"Light and night",texto:"The day runs from 10.3 hours at midwinter to 13.7 at midsummer. At night the usual spider and the scorpion come out, and they prowl the paths to the springs, which is where everyone walks."}],consejo:"The match is for the springs: whoever holds two eats, and whoever holds none fades. Raise the second anthill right beside one and defend the path, not the nest. Outside summer, everyone inside before dawn.",palabras:["oasis","desert","sahara","springs","place","africa"]}},[{etiqueta:e("D\xF3nde","Where"),valor:a("\xC1frica \xB7 27\xB0 norte \xB7 300 m","Africa \xB7 27\xB0 north \xB7 300 m")},{etiqueta:e("Clima","Climate"),valor:a("Des\xE9rtico","Desert")},{etiqueta:e("Verano / invierno","Summer / winter"),valor:a("35 \xB0C de d\xEDa \xB7 13 \xB0C de d\xEDa y \u22125 de madrugada","35 \xB0C by day \xB7 13 \xB0C by day and \u22125 before dawn")},{etiqueta:e("El d\xEDa","The day"),valor:a("De 10,3 a 13,7 h","From 10.3 to 13.7 h")},{etiqueta:e("Suelo","Ground"),valor:a("Arena llana y tres charcas","Flat sand and three ponds")},{etiqueta:e("Comida","Food"),valor:a("El 85 % junto a cuatro fuentes","85 % beside four springs")},n("oasis")],["mundo/sitio","mundo/noche","fauna/escorpion","hormiguero/despensa"]),o("amazonas","idioma",{es:{titulo:"El Amazonas",subtitulo:"La selva ecuatorial: sin a\xF1o, y espesa",resumen:"La casa de la cortadora. La cuenca del Amazonas, 3\xB0 sur y 100 metros sobre el mar: clima ecuatorial, el \xFAnico que no tiene a\xF1o \u2014las cuatro estaciones caben en dos grados\u2014 y doce horas de luz los trescientos sesenta y cinco d\xEDas. Un r\xEDo que no se seca, una vega que se inunda, de la flora m\xE1s densa del cat\xE1logo y comida por todas partes.",bloques:[{titulo:"El a\xF1o",texto:"Primavera y oto\xF1o a 27 grados de d\xEDa y 23 de madrugada; verano a 28 y 24; invierno a 26 y 22. La estaci\xF3n no es informaci\xF3n: no hiela nunca, la noche apenas refresca cuatro grados y lo \xFAnico que cambia con el a\xF1o es cu\xE1nto brota."},{titulo:"El suelo",texto:"Sin piedras y casi llano \u2014cinco niveles\u2014: un R\xCDO que no se seca nunca, dos terrazas de vega con cuatro lagos que se anegan en la crecida, y tierra firme detr\xE1s. Un hormiguero fundado en la vega come bien y puede ahogarse con la crecida. La hierba es espesa y frena hasta un cuarenta por ciento, y la flora es de las m\xE1s densas del cat\xE1logo, una vez y media la de siempre en manchas grandes: hay comida por todas partes y, por lo mismo, vecinos por todas partes."},{titulo:"La luz y la noche",texto:"El d\xEDa es siempre el mismo: de 11,8 a 12,2 horas. La noche es de calor y salen las dos ara\xF1as, la de siempre y la errante, y la escolopendra, la que persigue desde m\xE1s lejos."}],consejo:"La cortadora est\xE1 en casa: hormigueros enormes y obreras baratas para un sitio donde sobra comida y falta sitio. Sin invierno ni noche larga, aqu\xED no se sobrevive, se compite: la orilla es la mejor despensa y la vega se inunda, as\xED que la partida se juega entre comer abajo y dormir seco.",palabras:["amazonas","selva","ecuatorial","cortadora","atta","sitio","am\xE9rica","sudam\xE9rica","sin estaciones"]},en:{titulo:"The Amazon",subtitulo:"The equatorial rainforest: no year, and thick",resumen:"Home of the leafcutter ant. The Amazon basin, 3\xB0 south and 100 metres above the sea: equatorial climate, the only one with no year at all \u2014 the four seasons fit within two degrees \u2014 and twelve hours of light all three hundred and sixty-five days. A river that never dries, a floodplain that goes under, some of the densest flora in the catalogue and food everywhere.",bloques:[{titulo:"The year",texto:"Spring and autumn at 27 degrees by day and 23 before dawn; summer at 28 and 24; winter at 26 and 22. The season is not information: it never freezes, the night cools by barely four degrees and the only thing the year changes is how much sprouts."},{titulo:"The ground",texto:"No stones and almost flat \u2014 five levels \u2014: a RIVER that never dries, two floodplain terraces with four lakes that go under in the flood, and firm land behind. An anthill founded on the floodplain eats well and can drown in the flood. The grass is thick and slows ants by up to forty percent, and the flora is among the densest in the catalogue, one and a half times the usual in big patches: there is food everywhere and, for the same reason, neighbours everywhere."},{titulo:"Light and night",texto:"The day is always the same: from 11.8 to 12.2 hours. Nights are warm and both spiders come out, the usual one and the wandering one, and the centipede, the one that chases from furthest away."}],consejo:"The leafcutter is at home: enormous anthills and cheap workers for a place with food to spare and no room. With no winter and no long night, here you do not survive, you compete: the shore is the best larder and the floodplain goes under, so the match is played between eating low and sleeping dry.",palabras:["amazon","rainforest","jungle","equatorial","leafcutter","atta","place","america","south america","no seasons"]}},[{etiqueta:e("D\xF3nde","Where"),valor:a("Am\xE9rica \xB7 3\xB0 sur \xB7 100 m","America \xB7 3\xB0 south \xB7 100 m")},{etiqueta:e("Clima","Climate"),valor:a("Ecuatorial","Equatorial")},{etiqueta:e("Verano / invierno","Summer / winter"),valor:a("28 \xB0C de d\xEDa \xB7 26 \xB0C de d\xEDa y 22 de madrugada","28 \xB0C by day \xB7 26 \xB0C by day and 22 before dawn")},{etiqueta:e("El d\xEDa","The day"),valor:a("De 11,8 a 12,2 h","From 11.8 to 12.2 h")},{etiqueta:e("Relieve","Relief"),valor:a("5 niveles: r\xEDo, vega y tierra firme","5 levels: river, floodplain and firm land")},{etiqueta:e("Flora","Flora"),valor:a("1,6\xD7, manchas de radio 5","1.6\xD7, patches of radius 5")},n("amazonas"),{etiqueta:e("Su especie","Its species"),valor:a("La cortadora (Atta)","The leafcutter ant (Atta)")}],["especies/cortadora","mundo/sitio","mundo/noche","fauna/arana-errante"]),o("noche","ojo",{es:{titulo:"La noche",subtitulo:"Menos vista, otras amenazas",resumen:"Al caer la luz el mapa se cierra: se explora menos lejos, los insectos del d\xEDa desaparecen y sale a cazar la ara\xF1a. A la que anda se la ve venir; a la que vuela se la lleva la noche sin que se vea qu\xE9 fue.",bloques:[{titulo:"La vista",texto:"El radio con el que una hormiga destapa niebla, localiza comida Y DETECTA al enemigo va CON LA LUZ: a pleno d\xEDa ve algo m\xE1s lejos que su rasgo y en noche cerrada se queda en la d\xE9cima parte \u2014pr\xE1cticamente ciega\u2014. De noche no solo ve menos: descubre y engancha al enemigo dentro de ese mismo radio menguado, as\xED que reacciona tarde y pelea peor."},{titulo:"La ara\xF1a errante",texto:"De noche sale a cazar una ara\xF1a, y caza como cazan de verdad: se acerca a la hormiga que pilla lejos y sola, la mata y SE RETIRA A DIGERIRLA \u2014 una pieza por salida. Sale una por colonia, y a la que anda no se la lleva nadie sin aviso: la ara\xF1a se ve venir, y cualquier hormiga con orden de CAZAR la para antes de que cobre. Lo que la alimenta es la hormiga rezagada. A la que va POR EL AIRE no la caza ella: a esa se la lleva la noche en el acto, reina incluida \u2014 el vuelo nupcial se hace de d\xEDa o se paga."},{titulo:"El relevo de la fauna",texto:"Los insectos diurnos se retiran al anochecer y no brota ninguno hasta el alba. Las carcasas del d\xEDa siguen en el suelo y se pueden despiezar."}],consejo:"Guarece a la colonia antes del anochecer, y usa la marcha \xABhasta el amanecer\xBB para no mirar la espera.",palabras:["noche","ara\xF1a","arana","vista","amanecer","cazar","vuelo"]},en:{titulo:"The night",subtitulo:"Less sight, other threats",resumen:"When the light falls the map closes in: you scout less far, daytime insects vanish and the spider comes out to hunt. What walks sees it coming; what flies is taken by the night without you ever seeing what did it.",bloques:[{titulo:"Sight",texto:"The radius an ant uses to lift fog, spot food AND pick out an enemy GOES WITH THE LIGHT: in broad daylight it reaches a little past her trait, and in full night it falls to a tenth \u2014 all but blind. At night she does not only see less: she spots and engages the enemy within that same shrunken radius, so she reacts late and fights worse."},{titulo:"The wandering spider",texto:"At night a spider goes hunting, and it hunts the way hunters do: it closes on the ant it catches far and alone, kills her and WITHDRAWS TO DIGEST \u2014 one kill per outing. One comes out per colony, and nothing takes a walking ant without warning: the spider can be seen coming, and any ant with the HUNT order stops it before it collects. What feeds it is the ant that lags behind. It does not hunt what is IN THE AIR: that one the night takes on the spot, queens included \u2014 the nuptial flight happens by day or it is paid for."},{titulo:"The wildlife shift",texto:"Daytime insects withdraw at dusk and none sprout until dawn. The day\u2019s carcasses stay on the ground and can still be butchered."}],consejo:"Shelter the colony before nightfall, and use the \u201Cuntil dawn\u201D gear so you don\u2019t watch the wait.",palabras:["night","spider","sight","dawn","hunt","flight"]}},null,["mundo/clima","mundo/fauna","mundo/invierno"]),o("invierno","candado",{es:{titulo:"El invierno",subtitulo:"La estaci\xF3n que se pasa bajo techo",resumen:"Brota un tercio de comida, los d\xEDas son cortos y bajo cinco grados el exterior congela. Se sobrevive con lo acumulado en las estaciones buenas.",bloques:[{titulo:"La helada",texto:"Por debajo de cinco grados cada turno fuera acumula escarcha, m\xE1s deprisa cuanto m\xE1s arrecia el fr\xEDo, y en plena helada unos ciento veinte turnos a la intemperie son la sentencia \u2014y no todas aguantan igual\u2014. Pasar una noche de invierno fuera ni se intenta. El deshielo o guarecerse la borran del todo. Cu\xE1nto muerde depende de D\xD3NDE juegues: el oce\xE1nico apenas hiela, el continental hiela tambi\xE9n de d\xEDa, y hay dos \u2014el tropical y el ecuatorial\u2014 donde la escarcha no existe y el invierno solo se nota en que brota menos. Y EL FR\xCDO VA POR LA CASILLA QUE PISA CADA UNA: el term\xF3metro marca la media ladera; lo alto, expuesto, hiela antes de madrugada y se templa antes al sol, y lo bajo, a la sombra, al rev\xE9s: m\xE1s fresco de d\xEDa y m\xE1s templado de noche."},{titulo:"El letargo",texto:"Con hielo las hormigas se arrastran: en helada cerrada andan a la d\xE9cima parte de su paso, y el fr\xEDo las va frenando desde los cinco grados. La que sale lejos no vuelve \u2014 no le da tiempo."},{titulo:"El acopio",texto:"La reserva de comida es local: cada hormiguero consume la suya. Ll\xE9nalas en primavera y verano, cava granero y pasa el invierno con la guarnici\xF3n dentro."}],consejo:"El invierno no es para ganar terreno: es para llegar vivo a la primavera con la comida almacenada a\xFAn a la mitad.",palabras:["invierno","helada","acopio","comida almacenada","despensa","escarcha"]},en:{titulo:"The winter",subtitulo:"The season you spend indoors",resumen:"A third of the food sprouts, days are short and below five degrees the outside freezes. You survive on what the good seasons stored.",bloques:[{titulo:"The freeze",texto:"Below five degrees every turn outside builds frost, faster the harder the cold bites, and in a full freeze about one hundred twenty turns in the open are a death sentence \u2014and not every ant lasts the same\u2014. Spending a winter night outside is not even worth trying. Thaw or shelter wipes it clean. How hard it bites depends on WHERE you play: the oceanic one barely freezes, the continental one freezes by day as well, and there are two \u2014 tropical and equatorial \u2014 where frost does not exist at all and winter shows up only as fewer sprouts. And THE COLD GOES BY THE CELL EACH ANT STANDS ON: the thermometer shows mid-slope; high ground, exposed, freezes first before dawn and warms first in the sun, and low ground, in the shade, the other way round: cooler by day and milder at night."},{titulo:"Torpor",texto:"On ice ants crawl: in a hard freeze they walk at a tenth of their stride, and the cold slows them from five degrees down. The one that ranges far does not come back \u2014 there is no time."},{titulo:"Stockpiling",texto:"Food storage is local: each anthill consumes its own reserve. Fill it in spring and summer, dig granary space, and spend the winter with the garrison inside."}],consejo:"Winter is not for taking ground: it is for reaching spring alive with the stored food still half full.",palabras:["winter","freeze","stockpile","stored food","pantry","frost"]}},null,["mundo/clima","mundo/sitio","hormiguero/despensa"]),o("fauna","bicho",{es:{titulo:"Los bichos del campo",subtitulo:"Comida que anda, y algunos que te comen a ti",resumen:"El campo est\xE1 vivo: presas que huyen, herb\xEDvoras que se zampan tu comida y cazadoras que se llevan hormigas. Todo bicho abatido queda de carcasa, y la carcasa se despieza en el sitio: cada hormiga pegada arranca su trozo y lo apunta a la despensa de su hormiguero.",bloques:[{titulo:"Tres dietas",texto:"La PRESA solo huye \u2014pulg\xF3n, mariquita, escarabajo\u2014 y es comida con patas. La HERB\xCDVORA (oruga, saltamontes) busca tus migas, se las come y ENGORDA con ellas: cazarla recupera parte de lo que se llev\xF3. La INSECT\xCDVORA va a por tus hormigas: la avispa persigue, pica con el abdomen y, herida o rodeada, se escapa por el aire."},{titulo:"Morder es querer",texto:"Al bicho manso solo lo muerde quien va a por \xE9l, con la orden de CAZAR o de ATACAR: cruzarse con uno ya no lo mata. Al que muerde se le defiende todo el mundo, porque el que ataca es \xE9l. Y la presa acorralada cobra el despiece: un escarabajo cocea y una oruga se sacude, as\xED que la pieza grande cuesta cerca de una hormiga."},{titulo:"La estaci\xF3n decide qui\xE9n sale",texto:"Los brotes reponen el campo cada pocas decenas de turnos, en tandas y nunca junto a un hormiguero. Con estaciones, en primavera y verano brotan los pac\xEDficos y en oto\xF1o e invierno los que muerden. De noche el campo se vac\xEDa. Y si en el di\xE1logo de partida pones Amenazas: Ninguna, no hay fauna en absoluto: ni brotes, ni ara\xF1a, ni marabunta."}],consejo:"Una carcasa es una despensa que no se mueve: manda varias a despiezarla y entra a trozos. Y LO QUE PAGA SE VE A OJO \u2014 la carne de un bicho va con su tama\xF1o, as\xED que la lib\xE9lula llena la despensa y el pulg\xF3n es una propina\u2014; lo que cambia es lo que cuesta: la grande te pide manada y la peque\xF1a sale gratis.",palabras:["fauna","bichos","insectos","avispa","oruga","escarabajo","carcasa","despiece","cazar","amenazas"]},en:{titulo:"The creatures of the field",subtitulo:"Food that walks, and a few that eat you",resumen:"The field is alive: prey that flees, herbivores that devour your food and hunters that carry off ants. Every creature brought down is left as a carcass, and a carcass is butchered where it lies: each ant next to it tears off its share and books it to its own anthill pantry.",bloques:[{titulo:"Three diets",texto:"PREY only flees \u2014 aphid, ladybird, beetle \u2014 and is food on legs. The HERBIVORE (caterpillar, grasshopper) hunts for your crumbs, eats them and FATTENS on them: killing it recovers part of what it took. The INSECTIVORE comes for your ants: the wasp chases, stings with its abdomen and, wounded or surrounded, escapes through the air."},{titulo:"Biting means meaning it",texto:"A harmless creature is only bitten by ants that came for it, under the HUNT or ATTACK order: bumping into one no longer kills it. Whatever bites is fought by everyone, because it is the one attacking. And cornered prey charges for the butchering: a beetle kicks and a caterpillar thrashes, so a big carcass costs close to one ant."},{titulo:"The season picks who shows up",texto:"Spawns restock the field every few dozen turns, in batches and never beside an anthill. With seasons on, spring and summer bring out the harmless ones and autumn and winter the biting ones. At night the field empties. And if you set Threats: None in the match dialog there is no wildlife at all: no spawns, no spider, no army ants."}],consejo:"A carcass is a pantry that does not run: send several ants to butcher it and it comes home in pieces. AND WHAT IT PAYS IS VISIBLE \u2014 a creature\u2019s meat follows its size, so a dragonfly fills the pantry and an aphid is a tip; what changes is the price: a big one asks for a pack, a small one is free.",palabras:["wildlife","fauna","insects","wasp","caterpillar","beetle","carcass","butcher","hunt","threats"]}},[{etiqueta:e("Dietas","Diets"),valor:a("Presa \xB7 herb\xEDvora \xB7 insect\xEDvora","Prey \xB7 herbivore \xB7 insectivore")},{etiqueta:e("Bichos vivos a la vez","Creatures alive at once"),valor:a("De 2 a 40, seg\xFAn amenazas","From 2 to 40, by threat level")},{etiqueta:e("Sin fauna","No wildlife"),valor:a("Amenazas: Ninguna","Threats: None")}],["fauna/pulgon","fauna/avispa","fauna/arana","mundo/marabunta","mundo/noche","hormiguero/despensa"]),o("marabunta","hormiga",{es:{titulo:"La marabunta",subtitulo:"Un frente anunciado que cruza el mapa y se va",resumen:"En los sitios de selva y sabana, cada varios miles de turnos se pone en marcha un frente de legionarias. No es una emboscada: se anuncia con antelaci\xF3n, se dice por d\xF3nde entra y la barra cuenta lo que falta. Entra por un borde, cruza en l\xEDnea recta mordiendo lo que se le pone delante y se va por el otro lado.",bloques:[{titulo:"El aviso",texto:`Doscientos turnos antes salta el anuncio con el rumbo \u2014por el este, por el oeste, por el norte o por el sur\u2014 y un contador de lo que queda. Con estaciones solo llega en oto\xF1o e invierno, que es cuando el campo se pone bravo. Mientras el frente cruza, no brota ning\xFAn otro bicho. Y no sale en todas partes: solo en ${s.n} de los ${s.total} sitios, los de selva y sabana: ${s.es}.`},{titulo:"El frente",texto:"Llega formado en l\xEDnea perpendicular a su rumbo y avanza SIEMPRE: no duerme de noche, no se para a esperar y no le hace falta que nadie la vea. No persigue a nadie \u2014muerde lo que le queda al paso\u2014 y cada una aguanta poqu\xEDsimo y deja poca carne. Lo que hace da\xF1o es que son muchas y no se desv\xEDan."},{titulo:"Contrajuego",texto:"Tres, y se eligen con el aviso en la mano: guarecer a la colonia, apartar del corredor lo que est\xE9 en su camino, o plantarle un muro de guerreras. A la marabunta se le defiende todo el mundo por estar pegada, pero la orden de CAZAR no la toma como objetivo: contra ella se ATACA o se aguanta."}],consejo:"Cuando salte el aviso, mira el rumbo antes que el reloj: apartar una columna cuesta unos turnos de marcha, y que la pille cargada cuesta la columna entera.",palabras:["marabunta","legionarias","frente","evento","aviso","amenazas"]},en:{titulo:"The army ants",subtitulo:"An announced front that crosses the map and leaves",resumen:"In the jungle and savannah places, every few thousand turns a front of army ants sets off. It is not an ambush: it is announced in advance, it says which side it comes in from and the top bar counts down. It enters at one edge, crosses in a straight line biting whatever stands in the way and leaves by the far side.",bloques:[{titulo:"The warning",texto:`Two hundred turns ahead the announcement fires with the heading \u2014 from the east, the west, the north or the south \u2014 and a countdown. With seasons on it only arrives in autumn and winter, which is when the field turns rough. While the front is crossing, no other creature spawns. And it does not come everywhere: only in ${s.n} of the ${s.total} places, the jungle and savannah ones: ${s.en}.`},{titulo:"The front",texto:"It arrives formed in a line perpendicular to its heading and it ALWAYS advances: it does not sleep at night, it does not stop to wait and it does not need anyone to see it. It chases nobody \u2014 it bites whatever is left in its path \u2014 and each one is very frail and leaves little meat. What hurts is that there are many and they never swerve."},{titulo:"Counterplay",texto:"Three options, chosen with the warning in hand: shelter the colony, move whatever stands in the corridor out of the way, or set a wall of warriors against it. Everyone fights army ants just by standing next to them, but the HUNT order does not target them: against this you ATTACK or you hold."}],consejo:"When the warning fires, check the heading before the clock: moving a column aside costs a few turns of marching, and getting caught while carrying costs the whole column.",palabras:["army ants","marabunta","front","event","warning","threats"]}},[{etiqueta:e("Aviso","Warning"),valor:a("200 turnos","200 turns")},{etiqueta:e("El frente","The front"),valor:a("De 14 a 30 bichos","From 14 to 30 creatures")},{etiqueta:e("Cu\xE1ndo llega","When it arrives"),valor:a("Oto\xF1o e invierno","Autumn and winter")},{etiqueta:e("D\xF3nde","Where"),valor:a(`${s.n} de los ${s.total} sitios`,`${s.n} of the ${s.total} places`)}],["mundo/fauna","mundo/invierno","hormiguero/defensa"]),...f?[o("agua","idioma",{es:{titulo:"El agua",subtitulo:"Lagos, islas y un r\xEDo: lo que no se cruza a pie si no se hiela",resumen:`Varios sitios tienen AGUA PERMANENTE: lagunas, algunas con isla (${m.es}), archipi\xE9lagos de islas grandes o peque\xF1as (${p.es}) y el r\xEDo del Amazonas. Ninguna hormiga la cruza a nado, no se funda ni se cava en ella; pero se ve a trav\xE9s, quien vuela la cruza y, cuando se hiela, su hielo se pisa. Aparte est\xE1 el charco que deja la lluvia, que sube y baja (ver La lluvia y los charcos).`,bloques:[{titulo:"Qu\xE9 es",texto:"Una casilla aparte, que no es suelo: a pie no la cruzan ni las hormigas ni los bichos de suelo\u2026 SALVO HELADA. Bajo cero las lagunas se hielan desde la orilla, m\xE1s adentro cuanto m\xE1s fr\xEDo \u2014unas dos casillas a cinco bajo cero, hasta ocho a diez bajo cero\u2014, y ese hielo se pisa como el suelo; ojo al deshielo, que la que siga encima cuando se funde se ahoga. En cambio el agua no tapa nada: se ve al otro lado, y la avispa, la abeja y la lib\xE9lula vuelan por encima."},{titulo:"Lagunas e islas",texto:"Las lagunas tienen cada una su forma y nunca caen encima de un hormiguero de salida: el camino por tierra existe siempre, y una porteadora que va al otro lado la rodea por la orilla. Las ISLAS, no: a una isla solo se llega volando (o, si el lago se hiela hasta ella, por el hielo). Una reina en vuelo nupcial puede posarse y fundar en ella si cabe el hormiguero \u2014no se funda a menos de siete casillas del agua\u2014: nadie llega a pie a atacarla\u2026 y sus obreras tampoco salen."},{titulo:"La orilla da de comer",texto:"La comida brota m\xE1s a menudo y m\xE1s gorda junto al agua y bajo los \xE1rboles. El agua es un obst\xE1culo y es tambi\xE9n la despensa del campo."}],consejo:"No mandes obreras a una isla: no hay camino y se quedan en la orilla. Si una reina rival funda en una isla, no la sitiar\xE1s a pie; y si fundas t\xFA, esa colonia vive de lo que cabe en ella.",palabras:["agua","fiordo","laguna","lago","isla","islote","archipi\xE9lago","r\xEDo","orilla","cruzar","volar"]},en:{titulo:"Water",subtitulo:"Lakes, islands and a river: what you cannot cross on foot unless it freezes",resumen:`Several places have PERMANENT WATER: lakes, some with an island (${m.en}), archipelagos of large or small islands (${p.en}) and the Amazon\u2019s river. No ant swims across it, nothing is founded or dug in it; but you can see across it, whatever flies crosses it and, when it freezes, its ice can be walked on. The puddle left by the rain is something else: it rises and falls (see Rain and puddles).`,bloques:[{titulo:"What it is",texto:"A cell of its own, not ground: neither ants nor ground creatures cross it on foot\u2026 UNLESS IT FREEZES. Below zero the lakes freeze from the shore, further in the colder it gets \u2014 about two cells at five below, up to eight at ten below \u2014, and that ice can be walked on like ground; mind the thaw, because whoever is still on it when it melts drowns. Water hides nothing, though: you see the other side, and the wasp, the bee and the dragonfly fly over it."},{titulo:"Lakes and islands",texto:"Each lake has its own shape and never lands on a starting nest: a land route always exists, and a carrier heading past a lake walks around its shore. Not ISLANDS: an island can only be reached by flying (or, if the lake freezes all the way to it, over the ice). A queen on her nuptial flight can land and found there if the nest fits \u2014 nothing is founded within seven cells of water \u2014: nobody reaches her on foot to attack\u2026 and her workers cannot leave either."},{titulo:"The shore feeds",texto:"Food sprouts more often and richer next to water and under the trees. Water is an obstacle, and it is also the field\u2019s pantry."}],consejo:"Do not send workers to an island: there is no path and they stop at the shore. If a rival queen founds on an island you will not besiege her on foot; and if you found there, that colony lives on what fits on it.",palabras:["water","fjord","lake","lagoon","island","islet","archipelago","river","shore","cross","fly"]}},[{etiqueta:e("D\xF3nde","Where"),valor:a("Lagunas, archipi\xE9lagos y el r\xEDo del Amazonas","Lakes, archipelagos and the Amazon\u2019s river")},{etiqueta:e("La isla","The island"),valor:a("Solo volando","Flying only")},{etiqueta:e("Qui\xE9n la cruza","Who crosses"),valor:a("La reina en vuelo, la avispa, la abeja y la lib\xE9lula; a pie, solo helada","The queen in flight, the wasp, the bee and the dragonfly; on foot, only when frozen")},{etiqueta:e("El hielo","The ice"),valor:a("Bajo 0 \xB0C, desde la orilla: ~2 casillas a \u22125 \xB0C, 8 a \u221210 \xB0C","Below 0 \xB0C, from the shore: ~2 cells at \u22125 \xB0C, 8 at \u221210 \xB0C")},{etiqueta:e("La vista","Sight"),valor:a("Pasa: el agua no tapa","Passes: water hides nothing")}],["mundo/lluvia","mundo/relieve","hormiguero/fundacion","fauna/libelula"])]:[]];export{T as TARJETAS_MUNDO};
